  if (now && cur.date) {
    const d = cur.date.day - now.day;
    if (d > 0) gap = mode.includes('沙盒') ? `事件参考日期还有 ${d} 天，可以先写自由旅行与日常。` : `正文时间比事件参考日期早 ${d} 天：先写赶路、训练和日常，必要时一两句带过几天，再自然进入事件。`;
  }
