    if (segs[1] === 'npcs' && segs[2] === 'records' && segs[3]) { const k = npcKeyFor(pkm.npcs.records, segs[3]) || (segs.length === 4 && isObj(o.value) ? npcKeyFor(pkm.npcs.records, o.value.name) : null); if (k) segs[3] = k; }
