function persistentFormTarget(mon){const raw=String(mon?.species||mon?.name||'').trim();const id=speciesId(raw)||raw.toLowerCase().replace(/[^a-z0-9]/g,'');return FORM_REPAIRS[id]||FORM_ALIASES[raw]||null;}
function repairPersistentMon(mon){
 const target=persistentFormTarget(mon),info=PERSISTENT_SPECIES[target];if(!info)return false;
 const old=String(mon.species||mon.name||''),oldHp=mon.hp,oldMax=Number(mon.maxHp);
 if(!mon.formRepair)mon.formRepair={from:old,to:info.name,previousAbility:mon.ability,previousHp:mon.hp,previousMaxHp:mon.maxHp,revision:'1.3.31'};
 mon.species=info.name;if(!mon.name||mon.name===old||FORM_ALIASES[mon.name])mon.name=info.name;
 const lv=Math.max(1,Math.min(100,Number(mon.lv||mon.level)||5));
 const iv=ivOk(Number(mon.stats_meta?.ivs?.hp))?Number(mon.stats_meta.ivs.hp):31;
 const max=target==='shedinja'?1:Math.floor((2*info.hp+iv)*lv/100)+lv+10;
 mon.maxHp=max;
 if(oldHp!=null&&Number.isFinite(Number(oldHp))){const ratio=oldMax>0?Math.max(0,Math.min(1,Number(oldHp)/oldMax)):Math.max(0,Math.min(1,Number(oldHp)/max));mon.hp=Number(oldHp)<=0?0:Math.max(1,Math.min(max,Math.round(ratio*max)));}
 mon.ability=W.PKMAbilityChoice.select(mon.ability,SPECIES[info.name]?.abilities||[],{});
 return true;
}
function repairPersistentRoster(pkm){for(const mon of [...(pkm.party?.slots||[]),...(pkm.party?.box||[])])if(hasMon(mon))repairPersistentMon(mon);}

