  el.addEventListener('dragstart', e => e.preventDefault());
  el.addEventListener('load', () => { if (!ballDrag) placeBall(el); }, true);   // 跟随的宝可梦图片加载完、尺寸变了以后再收回屏内
  el.addEventListener('pointerdown', e => {
    if (!e.isPrimary || (e.pointerType === 'mouse' && e.button !== 0) || !e.target.closest?.('.orb, .follower')) return;
    const r = el.getBoundingClientRect();
    ballDrag = { id: e.pointerId, sx: e.clientX, sy: e.clientY, x0: r.left, y0: r.top, w: r.width, h: r.height, target: e.target.closest('.orb, .follower'), pointerType: e.pointerType, moved: false };
  });
