    if (s.hp != null && isObj(s.pp)) { const pp = {}; for (const m of e.moves) if (Number.isFinite(Number(s.pp[m]))) pp[m] = Number(s.pp[m]); if (Object.keys(pp).length) e.pp = pp; }
